function abbreviateProduct(left: number, right: number): string {
    let c2 = 0, c5 = 0;
    for (let i = left; i <= right; i++) {
        let x = i;
        while (x % 2 === 0) { x /= 2; c2++; }
        while (x % 5 === 0) { x /= 5; c5++; }
    }
    const C = Math.min(c2, c5);
    let rem2 = C, rem5 = C;
    let exact = 1;
    let big = false;
    let high = 1;
    let suffix = 1;
    for (let i = left; i <= right; i++) {
        let x = i;
        while (rem2 > 0 && x % 2 === 0) { x /= 2; rem2--; }
        while (rem5 > 0 && x % 5 === 0) { x /= 5; rem5--; }
        if (!big) {
            exact *= x;
            if (exact >= 1e10) big = true;
        }
        high *= x;
        while (high >= 1e15) high /= 10;
        suffix = (suffix * x) % 100000;
    }
    if (!big) {
        return exact.toString() + "e" + C;
    }
    const pre = Math.floor(high).toString().substring(0, 5);
    const suf = suffix.toString().padStart(5, "0");
    return pre + "..." + suf + "e" + C;
}
