Scan the array once and track the index of the previous 1. When the next 1 appears at index `i`, the number of zeros between them is `i - prev - 1`. If that is less than `k`, return `false`. If the scan finishes without a violation, return `true`.

```typescript
function kLengthApart(nums: number[], k: number): boolean {
    let prev = -1;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === 1) {
            if (prev !== -1 && i - prev - 1 < k) return false;
            prev = i;
        }
    }
    return true;
};
```

