The approach is a level-order BFS. For each node, I record its parent and depth when it is visited. If x and y end up at the same depth with different parents, they are cousins.

Implementation: a queue holds `[node, parent, depth]` entries. When a node's value equals x or y, I store its parent and depth. At the end I compare them.

The starter snippet defines a function, not a class, so I keep the function signature exactly as given.

```typescript
/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */

function isCousins(root: TreeNode | null, x: number, y: number): boolean {
    if (!root) return false;
    let px: TreeNode | null = null, py: TreeNode | null = null;
    let dx = -1, dy = -1;
    const queue: [TreeNode, TreeNode | null, number][] = [[root, null, 0]];
    let head = 0;
    while (head < queue.length) {
        const [node, parent, depth] = queue[head++];
        if (node.val === x) {
            px = parent;
            dx = depth;
        } else if (node.val === y) {
            py = parent;
            dy = depth;
        }
        if (node.left) queue.push([node.left, node, depth + 1]);
        if (node.right) queue.push([node.right, node, depth + 1]);
    }
    return dx === dy && dx !== -1 && px !== py;
}
```

