Fixing the lowest unset bit is safe because every element is eventually paired with something. Only the order of operations matters for scoring, and the DP covers every order: the lowest unset element is paired at some operation, and the other pairs can come before or after it. Specifically, a mask is reached by any subset of pairs having been done, and the lowest unset bit is not forced to be the next pair in the optimal order. Restricting to the lowest unset bit would only enumerate the pair containing the lowest element as the next operation, so it would miss orderings where it is paired later.

To cover all orderings, loop over all unset pairs `(i, j)` instead. With `m = 14` there are 16384 masks and at most about 91 pairs each, which is fast.

```typescript
function maxScore(nums: number[]): number {
    const m = nums.length;
    const gcd = (a: number, b: number): number => {
        while (b) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    const g: number[][] = [];
    for (let i = 0; i < m; i++) {
        g.push(new Array(m).fill(0));
        for (let j = 0; j < m; j++) {
            if (i !== j) g[i][j] = gcd(nums[i], nums[j]);
        }
    }
    const size = 1 << m;
    const dp = new Array<number>(size).fill(-1);
    dp[0] = 0;
    const pop = (x: number): number => {
        let c = 0;
        while (x) {
            x &= x - 1;
            c++;
        }
        return c;
    };
    for (let mask = 0; mask < size; mask++) {
        if (dp[mask] < 0) continue;
        const k = pop(mask);
        if (k % 2 !== 0) continue;
        const idx = k / 2 + 1;
        for (let i = 0; i < m; i++) {
