            for (let j = i + 1; j < m; j++) {
                if (mask & (1 << j)) continue;
                const nm = mask | (1 << i) | (1 << j);
                const v = dp[mask] + idx * g[i][j];
                if (v > dp[nm]) dp[nm] = v;
            }
        }
    }
    return dp[size - 1];
};
