    for (let i = 0; i < m; i++) {
        score.push([]);
        for (let j = 0; j < m; j++) {
            let s = 0;
            for (let k = 0; k < n; k++) {
                if (students[i][k] === mentors[j][k]) s++;
            }
            score[i].push(s);
        }
    }
    const full = 1 << m;
    const dp: number[] = new Array(full).fill(-1);
    dp[0] = 0;
