        if (i >= m) continue;
        for (let j = 0; j < m; j++) {
            if (mask & (1 << j)) continue;
            const nm = mask | (1 << j);
            const v = dp[mask] + score[i][j];
            if (v > dp[nm]) dp[nm] = v;
        }
    }
