    let ans = 0;
    for (let i = 0; i < n; i++) {
        const x = nums[i];
        const c = cnt[x];
        if (c > 0) freq[c]--;
        cnt[x] = c + 1;
        freq[c + 1]++;
        if (c + 1 > maxF) maxF = c + 1;
