            } else {
                run = 0;
            }
        }
        return count >= m;
    };
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (can(mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
};
