function numTriplets(nums1: number[], nums2: number[]): number {
    const count = (a: number[], b: number[]): number => {
        const map = new Map<number, number>();
        for (let j = 0; j < b.length; j++) {
            for (let k = j + 1; k < b.length; k++) {
                const p = b[j] * b[k];
                map.set(p, (map.get(p) || 0) + 1);
