function regionsBySlashes(grid: string[]): number {
    const n = grid.length;
    const parent: number[] = [];
    for (let i = 0; i < n * n * 4; i++) parent.push(i);
    let count = n * n * 4;
    const find = (x: number): number => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (a: number, b: number): void => {
        const ra = find(a), rb = find(b);
        if (ra !== rb) {
            parent[ra] = rb;
            count--;
