```typescript
function removeInvalidParentheses(s: string): string[] {
    let left = 0, right = 0;
    for (const c of s) {
        if (c === '(') left++;
        else if (c === ')') {
            if (left > 0) left--;
            else right++;
        }
    }
    const res = new Set<string>();
    const n = s.length;
    const dfs = (i: number, open: number, l: number, r: number, cur: string): void => {
        if (i === n) {
            if (open === 0 && l === 0 && r === 0) res.add(cur);
            return;
        }
        const c = s[i];
        if (c === '(') {
            if (l > 0) dfs(i + 1, open, l - 1, r, cur);
            dfs(i + 1, open + 1, l, r, cur + c);
        } else if (c === ')') {
            if (r > 0) dfs(i + 1, open, l, r - 1, cur);
            if (open > 0) dfs(i + 1, open - 1, l, r, cur + c);
        } else {
            dfs(i + 1, open, l, r, cur + c);
        }
    };
    dfs(0, 0, left, right, "");
    return Array.from(res);
}
```

