```typescript
function sumOddLengthSubarrays(arr: number[]): number {
    const n = arr.length;
    let total = 0;
    for (let i = 0; i < n; i++) {
        const r = n - 1 - i;
        const evenL = Math.floor(i / 2) + 1;
        const oddL = Math.floor((i + 1) / 2);
        const evenR = Math.floor(r / 2) + 1;
        const oddR = Math.floor((r + 1) / 2);
        const count = evenL * evenR + oddL * oddR;
        total += count * arr[i];
    }
    return total;
};
