function getCoprimes(nums: number[], edges: number[][]): number[] {
    const n = nums.length;
    const adj: number[][] = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        adj[a].push(b);
        adj[b].push(a);
    }
