    const cop: number[][] = Array.from({ length: 51 }, () => []);
    for (let a = 1; a <= 50; a++) {
        for (let b = 1; b <= 50; b++) {
            if (gcd(a, b) === 1) cop[a].push(b);
        }
    }
    const stackNode = new Array(51).fill(-1);
